#include "cartmesh2d/fv/FvMesh2D.hpp"
#include "cartmesh2d/io/MeshIO2D.hpp"
#include <cstdlib>
#include <new>
#include <iostream>
static std::size_t allocations=0;
void* operator new(std::size_t size) {++allocations;if(void* p=std::malloc(size?size:1))return p;throw std::bad_alloc();}
void operator delete(void* p) noexcept {std::free(p);}
void operator delete(void* p,std::size_t) noexcept {std::free(p);}
int main(int argc,char** argv) {
    if(argc!=2)return 2;
    const auto read=cartmesh2d::readCm2dTopology(argv[1]);
    if(!read.valid())return 3;
    const auto mesh=cartmesh2d::fv::makeFvMesh2D(read.topology);
    allocations=0;
    for(int i=0;i<10;++i)cartmesh2d::fv::validateFvMesh2D(mesh);
    const auto count=allocations;
    std::cout<<"{\"validationCalls\":10,\"cells\":"<<mesh.cells.size()<<",\"faces\":"<<mesh.faces.size()<<",\"operatorNewCalls\":"<<count<<"}\n";
}
